; DSYS.S - SYSTEM PAGE RENDERER

DSYSRENDER:
    JSR CLEARSCREEN
    JSR DRAWFRAME
    
    LDA #5
    STA $72
    LDA #2
    STA $77
    LDX #<SYSTITLESTR
    LDY #>SYSTITLESTR
    JSR PRINTAT
    
    LDA #7
    STA $72
    LDX #<SYSLABEL1
    LDY #>SYSLABEL1
    JSR PRINTAT
    
    LDA #9
    STA $72
    LDX #<SYSLABEL2
    LDY #>SYSLABEL2
    JSR PRINTAT
    RTS
